using System; using System.Collections.Generic; using System.Reflection; using BrawlLib.SSBB.ResourceNodes;
class T { static void P(object o,string ind){ foreach(var p in o.GetType().GetProperties(BindingFlags.Public|BindingFlags.Instance)){ if(p.DeclaringType==typeof(ResourceNode)) continue; if(p.GetIndexParameters().Length>0) continue; object v=null; try{v=p.GetValue(o,null);}catch{continue;} if(v is System.Collections.ICollection && !(v is string)) { var c=(System.Collections.ICollection)v; if(c.Count>64){Console.WriteLine(ind+p.Name+"=[n="+c.Count+"]");continue;} var s=""; foreach(var x in c) s+=x+","; Console.WriteLine(ind+p.Name+"=["+s+"]"); } else Console.WriteLine(ind+p.Name+"="+v);} }
 static void W(ResourceNode n,int d,string f){ bool m = n.GetType().Name.Contains(f)||f=="*"; if(m){Console.WriteLine(new string(' ',d*2)+"# "+n.GetType().Name+" '"+n.Name+"'"); P(n,new string(' ',d*2+2));} List<ResourceNode> ch=null; try{ch=n.Children;}catch{} if(ch==null)return; foreach(var c in ch) W(c,d+1,f);} 
 static int Main(string[] a){ var r=NodeFactory.FromFile(null,a[0]); W(r,0,a[1]); return 0; } }
